def P(id, name, qa, note, user="", defect="—", deck=True, b1440=True, b390=True, spec=None):
    d = {"id": id, "name": name, "qa": qa, "note": note, "user": user, "defect": defect, "dev": "—",
         "deck": f"deck/{id}.jpg" if deck is True else deck, "b1440": f"build/{id}-1440.jpg" if b1440 is True else b1440, "b390": f"build/{id}-390.jpg" if b390 is True else b390}
    if spec: d["spec"] = spec; d["deck_empty"] = "Spec only (no crop)"
    return d
